CREATE OR REPLACE FUNCTION get_next_order_sequence(seq_name TEXT)
RETURNS BIGINT
LANGUAGE plpgsql
AS $$
BEGIN
    -- Create sequence if it doesn't exist
    EXECUTE format('CREATE SEQUENCE IF NOT EXISTS %I START 1 INCREMENT 1', seq_name);

    -- Get and return next value atomically
    RETURN nextval(seq_name);
END;
$$;
